# Let me verify the BFS result by checking path lengths
def find_shortest_path_length(adj, start, target):
    """Find the shortest path length from start to target using BFS."""
    if start == target:
        return 0

    visited = set()
    queue = deque([(start, 0)])

    while queue:
        node, depth = queue.popleft()

        if node in visited:
            continue
        visited.add(node)

        for neighbor in adj.get(node, []):
            if neighbor == target:
                return depth + 1
            if neighbor not in visited:
                queue.append((neighbor, depth + 1))

    return -1  # Not reachable

